package com.gmail.manhle240406.project.media;
import android.graphics.Bitmap;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import com.google.android.gms.tasks.*;
import org.junit.*;
import org.junit.runner.RunWith;
import java.io.ByteArrayOutputStream;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.*;
import static org.junit.Assert.*;

/** Hermetic transport: no Firebase requests, uploads, identity changes or private fixtures. */
@RunWith(AndroidJUnit4.class)
public final class SessionImageCacheDeviceTest {
 private final AtomicInteger calls=new AtomicInteger();private final AtomicLong now=new AtomicLong(1);
 private byte[] bytes;
 @Before public void setup(){SessionImageCache.clear();Bitmap b=Bitmap.createBitmap(512,512,Bitmap.Config.ARGB_8888);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,out);bytes=out.toByteArray();b.recycle();SessionImageCache.clock=now::get;SessionImageCache.source=(id,v)->{calls.incrementAndGet();return Tasks.forResult(bytes);};}
 @After public void cleanup(){SessionImageCache.clear();SessionImageCache.source=ManagedMediaClient::image;SessionImageCache.clock=android.os.SystemClock::elapsedRealtime;}
 private Bitmap read(String uid,String id)throws Exception{Bitmap b=Tasks.await(SessionImageCache.get(uid,id,"thumbnail"),5,TimeUnit.SECONDS);InstrumentationRegistry.getInstrumentation().waitForIdleSync();return b;}
 @Test public void authLayoutStartsWithLoadingInsteadOfLegacyAccountUi(){InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{android.content.Context context=new android.view.ContextThemeWrapper(InstrumentationRegistry.getInstrumentation().getTargetContext(),com.gmail.manhle240406.project.R.style.Theme_Project_Auth);android.view.View root=android.view.LayoutInflater.from(context).inflate(com.gmail.manhle240406.project.R.layout.activity_auth,null);assertEquals(android.view.View.GONE,root.findViewById(com.gmail.manhle240406.project.R.id.auth_form).getVisibility());assertEquals(android.view.View.VISIBLE,root.findViewById(com.gmail.manhle240406.project.R.id.auth_startup_loading).getVisibility());});}
 @Test public void loadingStateFitsPhoneVariants(){InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{try{for(String variant:new String[]{"portrait","landscape","dark","large"}){android.content.Context base=InstrumentationRegistry.getInstrumentation().getTargetContext();android.content.res.Configuration config=new android.content.res.Configuration(base.getResources().getConfiguration());config.uiMode=(config.uiMode&~android.content.res.Configuration.UI_MODE_NIGHT_MASK)|(variant.equals("dark")?android.content.res.Configuration.UI_MODE_NIGHT_YES:android.content.res.Configuration.UI_MODE_NIGHT_NO);config.fontScale=variant.equals("large")?1.3f:1f;android.content.Context context=new android.view.ContextThemeWrapper(base.createConfigurationContext(config),com.gmail.manhle240406.project.R.style.Theme_Project_Auth);android.view.View root=android.view.LayoutInflater.from(context).inflate(com.gmail.manhle240406.project.R.layout.activity_auth,null);int width=variant.equals("landscape")?1600:720,height=variant.equals("landscape")?720:1600;root.measure(android.view.View.MeasureSpec.makeMeasureSpec(width,android.view.View.MeasureSpec.EXACTLY),android.view.View.MeasureSpec.makeMeasureSpec(height,android.view.View.MeasureSpec.EXACTLY));root.layout(0,0,width,height);android.view.View loading=root.findViewById(com.gmail.manhle240406.project.R.id.auth_startup_loading);assertTrue(loading.getHeight()>0);assertTrue(loading.getBottom()<=height);Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);root.draw(new android.graphics.Canvas(bitmap));java.io.File dir=new java.io.File(base.getExternalFilesDir(null),"cache-loading-audit");assertTrue(dir.mkdirs()||dir.isDirectory());try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,variant+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}}catch(Exception error){throw new AssertionError(error);}});}
 @Test public void repeatedBindsReuseOneDecodedBitmap()throws Exception{Bitmap first=read("a","one");for(int i=0;i<100;i++)assertSame(first,read("a","one"));assertEquals(1,calls.get());}
 @Test public void accountsAndVariantsNeverShareEntries()throws Exception{read("a","one");read("b","one");Tasks.await(SessionImageCache.get("a","one","display"),5,TimeUnit.SECONDS);assertEquals(3,calls.get());}
 @Test public void expiryAndExplicitInvalidationFetchFreshCopies()throws Exception{read("a","one");now.addAndGet(60_001);read("a","one");assertEquals(2,calls.get());SessionImageCache.clear();read("a","one");assertEquals(3,calls.get());}
 @Test public void manyImagesStayWithinTwelveMiB()throws Exception{for(int i=0;i<24;i++)read("a","image"+i);assertTrue(SessionImageCache.bytes()<=12*1024*1024);int before=calls.get();read("a","image0");assertEquals(before+1,calls.get());}
 @Test public void invalidatedInflightResultCannotRepopulateCache()throws Exception{TaskCompletionSource<byte[]> response=new TaskCompletionSource<>();SessionImageCache.source=(id,v)->{calls.incrementAndGet();return response.getTask();};Task<Bitmap> first=SessionImageCache.get("a","one","thumbnail");assertSame(first,SessionImageCache.get("a","one","thumbnail"));SessionImageCache.clear();response.setResult(bytes);try{Tasks.await(first,5,TimeUnit.SECONDS);fail("Old request must be fenced");}catch(java.util.concurrent.ExecutionException expected){}InstrumentationRegistry.getInstrumentation().waitForIdleSync();assertEquals(0,SessionImageCache.bytes());read("a","one");assertEquals(2,calls.get());}
 @Test public void failuresAreNotCachedAndOutstandingWorkIsBounded()throws Exception{TaskCompletionSource<byte[]> response=new TaskCompletionSource<>();SessionImageCache.source=(id,v)->response.getTask();java.util.List<Task<Bitmap>> work=new java.util.ArrayList<>();for(int i=0;i<64;i++)work.add(SessionImageCache.get("a","image"+i,"thumbnail"));assertEquals(64,SessionImageCache.pending());Task<Bitmap> rejected=SessionImageCache.get("a","overflow","thumbnail");assertTrue(rejected.isComplete());assertFalse(rejected.isSuccessful());SessionImageCache.clear();assertTrue(SessionImageCache.pending()<=4);response.setException(new java.io.IOException("test"));Tasks.await(Tasks.whenAllComplete(work),5,TimeUnit.SECONDS);InstrumentationRegistry.getInstrumentation().waitForIdleSync();}
}

